import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"益","description":"焦氏易林注 - 益","frontmatter":{"title":"益","description":"焦氏易林注 - 益"},"headers":[],"relativePath":"classics/jiaoyilin/042.md","filePath":"classics/jiaoyilin/042.md"}'),l={name:"classics/jiaoyilin/042.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="益" tabindex="-1">益 <a class="header-anchor" href="#益" aria-label="Permalink to “益”">​</a></h1><h3 id="益-1" tabindex="-1">益 <a class="header-anchor" href="#益-1" aria-label="Permalink to “益”">​</a></h3><h3 id="益之乾" tabindex="-1">益之乾 <a class="header-anchor" href="#益之乾" aria-label="Permalink to “益之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>下堂出門，東至九山。逢福值喜，得其安閑。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦《益》象。艮為堂，坤為下、為門，震出，震東，數九故曰九山。震為福喜，艮為山、為安。○至，汲古作西，依宋元本。</p><h3 id="益之坤" tabindex="-1">益之坤 <a class="header-anchor" href="#益之坤" aria-label="Permalink to “益之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>城上有鳥，自名破家。招呼鴆毒，為國災患。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《蒙》。○鴆，汲古作醜，依宋元本。</p><h3 id="益之屯" tabindex="-1">益之屯 <a class="header-anchor" href="#益之屯" aria-label="Permalink to “益之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>伯虎仲熊，德義淵泓。使敷五教，陰陽順序。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《隨》。○泓，宋元本作聞，依汲古。敷教，汲古作布榖，依宋元本。</p><h3 id="益之蒙" tabindex="-1">益之蒙 <a class="header-anchor" href="#益之蒙" aria-label="Permalink to “益之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>飲酒醉酗，跳起爭鬬。伯傷仲僵，東家治喪。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>依《比》之《鼎》校。○酗，宋元本作酣，且多手足紛拏四字。</p><h3 id="益之需" tabindex="-1">益之需 <a class="header-anchor" href="#益之需" aria-label="Permalink to “益之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>四目相視，稍近同軌。日昳之後，見吾伯姊。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>互離為目，兌數四，故曰四目。眣，日昃也。坎西，離與坎連，日向西，故曰日眣。兌為伯姊，本《大過》也。○軌，宋元本作機，依汲古。姊，汲古作姨，依宋元本。</p><h3 id="益之訟" tabindex="-1">益之訟 <a class="header-anchor" href="#益之訟" aria-label="Permalink to “益之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>隨時逐便，不失利門。多獲得福，富於封君。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>伏震為時、為逐，乾為門，巽為利，故曰利門。乾為福、為富、為君。○多，汲古作靈，依宋元本。</p><h3 id="益之師" tabindex="-1">益之師 <a class="header-anchor" href="#益之師" aria-label="Permalink to “益之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>隴西冀北，多見駿馬。去如猋揚，害不能傷。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>坎為西，坤為北，震為馬，坤坎亦為馬，故曰多見駿馬。坤為風，故曰猋揚。猋，音標，迴風也。坎為害、為傷，震解，故不傷。</p><h3 id="益之比" tabindex="-1">益之比 <a class="header-anchor" href="#益之比" aria-label="Permalink to “益之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>白龍黑虎，起伏俱怒。蚩尤敗走，死於魚首。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《坎》。汲古第三句多期戰盤空四字，依宋元本刪。</p><h3 id="益之小畜" tabindex="-1">益之小畜 <a class="header-anchor" href="#益之小畜" aria-label="Permalink to “益之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>鴻飛戾天，避害紫淵。雖有鋒門，不能危身。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>通《豫》。巽為鴻，在乾上，故曰戾天。坤為淵、為害，坎隱伏，故曰避害紫淵。離色紫也。鋒門，丁晏雲《藝文志》有逢門射法二篇，師古曰：即逢蒙。艮為鋒，坤為門，坎為矢，震為射，故鋒門。坤為身，《詩大雅》鳶飛戾天，註：戾，至也。</p><h3 id="益之履" tabindex="-1">益之履 <a class="header-anchor" href="#益之履" aria-label="Permalink to “益之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>平國不君，夏氏作亂。烏號竊發，靈公隕命。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>詳《臨》之《晉》。○君，汲古訛均，非，依元本。</p><h3 id="益之泰" tabindex="-1">益之泰 <a class="header-anchor" href="#益之泰" aria-label="Permalink to “益之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>江漢上游，政逆民憂。陰伐其陽，雄受其殃。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>坤為水，故曰江漢，在上故曰上游。坤為政、為逆、為民、為憂，陰上陽下，故曰陰伐其陽，雄受其殃。○受其，汲古作者受，依元本。</p><h3 id="益之否" tabindex="-1">益之否 <a class="header-anchor" href="#益之否" aria-label="Permalink to “益之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>東家殺牛，聞臭腥臊。神怒不顧，命衰絕周。亳社災燒，宋公夷誅。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>詳《噬嗑》之《巽》。命衰絕周者，言殷命將絕於周也。</p><h3 id="益之同人" tabindex="-1">益之同人 <a class="header-anchor" href="#益之同人" aria-label="Permalink to “益之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>西誅不服，恃強負力。倍道趨敵，師徒敗覆。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>丁雲：似指項梁。徒，汲古作走，非。卦伏《師》，師坎為西，坤為誅，震健，故恃強負力。震為大塗，巽為倍，故曰倍道趨敵。坤為師，徒為敗。</p><h3 id="益之大有" tabindex="-1">益之大有 <a class="header-anchor" href="#益之大有" aria-label="Permalink to “益之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>一婦六夫，亂擾不治。張亡季疾，莫適為公。政道壅塞，周君失邦。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>此用《益》象。上巽為婦，下震為夫，震數三，互艮亦為夫，亦數三，故一婦六夫。坤為亂，震為張，艮為季，坤為亡，坎為疾，故曰張亡季疾。震為公，初至五正反震，故曰莫適為公。坤為政，艮為道，艮止故壅塞。震為君、為周，坤為邦，坤喪故周君失邦。疾，汲古作莊，亡作王，依宋元本。後思王者強健，莊者嚴肅，張王季莊頗與下句莫適為公意合，而韻又協，或汲古是也。</p><h3 id="益之謙" tabindex="-1">益之謙 <a class="header-anchor" href="#益之謙" aria-label="Permalink to “益之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>配合相迎，利之四鄉。昏以為期，明星煌煌。欣喜奭懌，所言得當。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>坎為配合，坤為鄉，震卦數四，故曰四鄉。坎為昏，艮為明、為星，震為喜、為言。奭，盛也。○奭懌，宋元本作爽澤，依汲古。鄉，汲古作，依宋元本。</p><h3 id="益之豫" tabindex="-1">益之豫 <a class="header-anchor" href="#益之豫" aria-label="Permalink to “益之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>猿墮高木，不踒手足。握金懷玉，還歸其室。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《臨》。</p><h3 id="益之隨" tabindex="-1">益之隨 <a class="header-anchor" href="#益之隨" aria-label="Permalink to “益之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>卷領遁世，仁德不害。三聖攸同，周國茂興。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《震》。○領，汲古作舌。攸，元刊作欣，依宋本。</p><h3 id="益之蠱" tabindex="-1">益之蠱 <a class="header-anchor" href="#益之蠱" aria-label="Permalink to “益之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>去患脫厄，安無怵惕。上福喜堂，見我歡悅。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>互大坎為患、為厄、為怵惕，震為福喜，一陽上升，故去患脫厄而無懼也。艮為堂、為我，兌見。○患，汲古作危，歡作喜，均依汲古。</p><h3 id="益之臨" tabindex="-1">益之臨 <a class="header-anchor" href="#益之臨" aria-label="Permalink to “益之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>帶季兒良，時利權兵。將師合戰，敵不能當，趙魏以強。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>通《遁》。艮為季，巽為帶，故曰帶季，即帶佗。震為兒、為良，故曰兒良。《藝文志》有兒良一篇，列兵家。過秦論，帶佗、兒良並稱兵家，故曰權兵。艮為時，巽為利，坤為師，震為戰、為趙、為強。○時利，宋元本作明智，依汲古。</p><h3 id="益之觀" tabindex="-1">益之觀 <a class="header-anchor" href="#益之觀" aria-label="Permalink to “益之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>鵠思其雄，欲隨鳳東。順理羽翼，出次須日。中留北邑，復反其室。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>詳《明夷》之《益》。次須日中，汲古作自日中須，依宋元本。</p><h3 id="益之噬嗑" tabindex="-1">益之噬嗑 <a class="header-anchor" href="#益之噬嗑" aria-label="Permalink to “益之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>耳如驚鹿，不能定足。室家分散，各走匿竄。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>互坎為耳，震為驚、為鹿、為足，艮為室家，坎為匿。○匿竄與散韻，汲古作鼠匿，非，依宋元本。耳，汲古訛且。</p><h3 id="益之賁" tabindex="-1">益之賁 <a class="header-anchor" href="#益之賁" aria-label="Permalink to “益之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>甲乙丙丁，俱歸我庭。三醜六子，入門見母。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>震東方甲乙，離南丙丁，艮為庭、為我，震為歸，故曰俱歸我庭。艮居北，數三，故曰三醜。坎居子，數六，故曰六子。艮為門，伏巽為母，離為見。○歸，宋元本作位，依汲古。</p><h3 id="益之剝" tabindex="-1">益之剝 <a class="header-anchor" href="#益之剝" aria-label="Permalink to “益之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>躡華顛，觀浮雲。風不搖，雨不薄。心安吉，無患咎。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮為山、為顛，伏兌為西，故曰華顛。坤為雲、為風，兌為雨，兌伏，故雲不薄。坤為心、為患，艮安，故無。此皆三字句，元本刪不搖作四字句，非，依宋本、汲古。又薄元本作博，患作匿，亦非。</p><h3 id="益之復" tabindex="-1">益之復 <a class="header-anchor" href="#益之復" aria-label="Permalink to “益之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>德施流行，利之四鄉。雨師灑道，風伯逐殃。巡狩封禪，以告成功。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>震為德、為行，卦數四，坤為鄉，故曰四鄉。坤為師、為水，故曰雨師。坤為風，震為伯，故曰風伯。獨斷雲，雨師畢星、風伯箕星也。古者天下太平，天子必巡狩四方，封四方，封太山，禪梁父。震為言，故曰以告成功。</p><h3 id="益之無妄" tabindex="-1">益之無妄 <a class="header-anchor" href="#益之無妄" aria-label="Permalink to “益之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>水流趨下，遂成東海。求我所有，買鱔與鯉。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>詳《損》之《需》。</p><h3 id="益之大畜" tabindex="-1">益之大畜 <a class="header-anchor" href="#益之大畜" aria-label="Permalink to “益之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>和氣相薄，膏潤津澤，生我嘉穀。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>兌為和、為潤澤，震為生、為榖。</p><h3 id="益之頤" tabindex="-1">益之頤 <a class="header-anchor" href="#益之頤" aria-label="Permalink to “益之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>憂驚以除，禍不成災，安全以來。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>坤憂，震驚，艮安，正反艮故曰憂驚以除，禍不成災。互坤為災禍。</p><h3 id="益之大過" tabindex="-1">益之大過 <a class="header-anchor" href="#益之大過" aria-label="Permalink to “益之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>堅冰黃鳥，常哀悲愁。不見白粒，但睹藜蒿。數驚鷙鳥，為我心憂。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《噬嗑》。○白，汲古作甘，依宋元本，巽為白也。末句宋元本作飄為我憂，依汲古。</p><h3 id="益之坎" tabindex="-1">益之坎 <a class="header-anchor" href="#益之坎" aria-label="Permalink to “益之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>翕翕，隕墜崩顛。滅其令名，身命不全。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《謙》。下二句宋元本作滅其命身，依汲古。隕，各本皆作實，依《否》之《離》校。</p><h3 id="益之離" tabindex="-1">益之離 <a class="header-anchor" href="#益之離" aria-label="Permalink to “益之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>因禍受福，喜盈其室。通《坎》。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>互艮為室，震為喜。○室，汲古作身，依宋元本。</p><h3 id="益之鹹" tabindex="-1">益之鹹 <a class="header-anchor" href="#益之鹹" aria-label="Permalink to “益之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>陸居千里，不見河海，無有魚市。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>坤為陸、為千里、為河海，坤伏，故不見。巽為魚、為市，乾無，故曰無有魚市。○陸，宋元本作佳，依汲古。</p><h3 id="益之恆" tabindex="-1">益之恆 <a class="header-anchor" href="#益之恆" aria-label="Permalink to “益之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>鹿得美草，鳴呼其友。九族和睦，不憂飢乏。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>詳《益》之《恆》。</p><h3 id="益之遯" tabindex="-1">益之遯 <a class="header-anchor" href="#益之遯" aria-label="Permalink to “益之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>出門得黨，不逢禍殃。入戶自若，不見矛戟。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>乾為門戶，艮為黨，坤為禍殃，坤伏故不逢。艮為矛戟。巽為入、為伏，故不見矛戟。黨，助也。《論語》&quot;君子不黨&quot;註：相助為非曰黨。</p><h3 id="益之大壯" tabindex="-1">益之大壯 <a class="header-anchor" href="#益之大壯" aria-label="Permalink to “益之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>罍尊重席，命我嘉客。福佑久長，不見禍殃。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>震為尊罍、為席，兌卦數二，故曰重席。震為嘉、為客、為長，乾為福佑，坤為禍殃，坤伏故不見。○禍，汲古作咎，依宋元本。罍，汲古作累，依宋元本。</p><h3 id="益之晉" tabindex="-1">益之晉 <a class="header-anchor" href="#益之晉" aria-label="Permalink to “益之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>鴻雁俱飛，北就魚池。鱔鮪鰋鯉，眾多饒有。一笱獲兩，利得過倍。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《觀》。○鮪，汲古作佔，依宋元本校。第四句宋元本作多饒所有，汲古作眾鳥饒有，皆非，依《比》之《觀》校。笱，汲古作鳴，依宋元本。利得，宋元本作利之，汲古作得之，皆非，仍依《比》之《觀》校。</p><h3 id="益之明夷" tabindex="-1">益之明夷 <a class="header-anchor" href="#益之明夷" aria-label="Permalink to “益之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>當風奮翼，與鳥飛北。入我家國，見吾慶室。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>坤為風，震為翼，離為鳥，坤為北、為家國，坎為室，震喜，故曰慶室。</p><h3 id="益之家人" tabindex="-1">益之家人 <a class="header-anchor" href="#益之家人" aria-label="Permalink to “益之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>麒麟鳳凰，善政得祥。陰陽和調，國無災殃。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>詳《大有》之《旅》。</p><h3 id="益之睽" tabindex="-1">益之睽 <a class="header-anchor" href="#益之睽" aria-label="Permalink to “益之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>逐狐東山，水遏我前。深不可涉，失其後便。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>詳《大畜》之《震》。</p><h3 id="益之蹇" tabindex="-1">益之蹇 <a class="header-anchor" href="#益之蹇" aria-label="Permalink to “益之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>醜戌亥子，饑饉所生。陰為暴客，水絕我食。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>下艮，先天居戌，後天居醜，坎居亥子，醜戌亥子，皆在北方，北方屬水，《史記貨殖傳》水毀木飢，故曰饑饉所生，曰陰為暴客。北方坎水，故曰水絕我食。○所，宋元本作前，為作陽，均依汲古。</p><h3 id="益之解" tabindex="-1">益之解 <a class="header-anchor" href="#益之解" aria-label="Permalink to “益之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>狐狸雉兔，畏人逃去。分走竄匿，不知所處。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>詳《睽》之《大有》。○人，汲古作我。</p><h3 id="益之損" tabindex="-1">益之損 <a class="header-anchor" href="#益之損" aria-label="Permalink to “益之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>桀蹠惡人，使德不通。炎旱為殃，年穀大傷。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>坤為惡，故曰桀。伏巽為盜，故曰蹠。正反艮，故不通。震為使也。艮為火，故炎旱。震為年穀，兌毀故傷。○德，汲古作得，非，依宋元本。</p><h3 id="益之益" tabindex="-1">益之益 <a class="header-anchor" href="#益之益" aria-label="Permalink to “益之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>文王四乳，仁愛篤厚。子畜十男，無有夭折。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>詳《頤》之《節》。</p><h3 id="益之夬" tabindex="-1">益之夬 <a class="header-anchor" href="#益之夬" aria-label="Permalink to “益之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>兔乳在室，行來雀食。虎攫我子，長號不已。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦《益》象。震為兔，艮為室、為雀、為虎，艮手故曰攫。震為子、為長號，正反震故曰不已。○在，汲古作立，非，依宋元本。來，元本作求，攫訛懼，均依宋本、汲古。</p><h3 id="益之姤" tabindex="-1">益之姤 <a class="header-anchor" href="#益之姤" aria-label="Permalink to “益之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>土階明堂，禮讓益興。雄雌相得，使我無疾。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>通《復》。坤為上階、為禮，震為興。一陽臨五陰，故曰雄雌相得。坤為我、為疾，震解故無。</p><h3 id="益之萃" tabindex="-1">益之萃 <a class="header-anchor" href="#益之萃" aria-label="Permalink to “益之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>送金出門，並失玉丸。往來井上，破甕壞盆。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>坤為門，互艮為金，震為玉，互大坎為丸，震伏故失玉丸。兌為井，三至上正反兌，故曰往來井上。上疑為井，以重文作上，故訛為上也。震為甕、為盆，震覆故曰破，兌毀故也。往來井井，謂三至上正反兌也。井初至四亦正反兌，由此證《井彖》&quot;往來井井&quot;亦由正反兌，焦氏說之甚明也。○丸，汲古作兔，依宋元本。</p><h3 id="益之升" tabindex="-1">益之升 <a class="header-anchor" href="#益之升" aria-label="Permalink to “益之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>諷德誦功，美周盛隆。加其旦輔，光濟沖人。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>震為德、為功、為言，故曰諷誦。震為周、為旦、為沖人，言周公旦輔成王以成周德。○光，汲古作夬，依宋元本。</p><h3 id="益之困" tabindex="-1">益之困 <a class="header-anchor" href="#益之困" aria-label="Permalink to “益之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>盜竊滅身，二母不親。王后無黨，毀其寶靈。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>互巽為盜，艮為身，艮伏，故滅身。巽為母，正反巽相背，故曰二母，故曰不親。震為王、為寶，震伏故毀，兌為毀也。</p><h3 id="益之井" tabindex="-1">益之井 <a class="header-anchor" href="#益之井" aria-label="Permalink to “益之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>六月騤騤，各欲有至。專徵束裝，俟時旦明。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>詳《蹇》之《小過》。旦明，汲古作明旦，非，明與裝韻，依宋元本。惟有首句各本皆作六目睽睽，非，因下雲專徵，故知用六月出師詩也。時，各本作待，均依《小過》校。</p><h3 id="益之革" tabindex="-1">益之革 <a class="header-anchor" href="#益之革" aria-label="Permalink to “益之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>雀行求粒，誤入網罭。賴仁君子，復說歸室。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>離為雀、為網，巽為粒，伏震為仁、為脫、為歸，艮為君子、為室。○網，宋元本作罟，說作脫，均依汲古。說，古皆通脫。《易林》用古字多。</p><h3 id="益之鼎" tabindex="-1">益之鼎 <a class="header-anchor" href="#益之鼎" aria-label="Permalink to “益之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>仁德孔明，患禍不傷。期誓不至，室人銜恤。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。震為仁德、為孔，艮為明，故曰仁德孔明。坤為患禍，艮為室，震為人，故曰室人。震為銜，坤憂故曰銜恤。</p><h3 id="益之震" tabindex="-1">益之震 <a class="header-anchor" href="#益之震" aria-label="Permalink to “益之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>龜厭江海，陸行不止。自令枯槁，失其都市，雖憂無咎。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《節》。末句汲古作憂悔咎生，非，依宋元本。</p><h3 id="益之艮" tabindex="-1">益之艮 <a class="header-anchor" href="#益之艮" aria-label="Permalink to “益之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>孤獨特處，莫依為輔，心勞志苦。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>坎為孤，艮為獨，坎為心、為勞。○汲古心上多正字，心下多允濟神三字，作四句，依宋元本。</p><h3 id="益之漸" tabindex="-1">益之漸 <a class="header-anchor" href="#益之漸" aria-label="Permalink to “益之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>伯仲言留，叔子雲去。雖去無咎，主母大喜。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>通《歸妹》。震為伯，坎為仲，艮為叔，艮止故留，震往故去。巽為母，震為主、為喜，故曰主母大喜。○雖，汲古訛誰，依宋元本。雖去，宋元本作雖自，汲古作誰雲，依局本。</p><h3 id="益之歸妹" tabindex="-1">益之歸妹 <a class="header-anchor" href="#益之歸妹" aria-label="Permalink to “益之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>初憂不安，後得笑歡，雖懼無患。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>互坎為憂，震為笑，在外卦故曰後。</p><h3 id="益之豐" tabindex="-1">益之豐 <a class="header-anchor" href="#益之豐" aria-label="Permalink to “益之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>好戰亡國，師不以律。稱上隕墜，齊侯狠戾，被其災祟。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>震為戰，坤為國、為師，坎為律，坤坎皆伏不見，故曰亡國、曰師不以律。巽為齊，震為諸侯、為狠，離為災，似指頃公。○被其，宋元本作其被，依汲古。稱上二字疑有訛。</p><h3 id="益之旅" tabindex="-1">益之旅 <a class="header-anchor" href="#益之旅" aria-label="Permalink to “益之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>鹿在澤陂，豺傷其麑，洋血獨哀。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>通《節》。震為鹿，兌為澤陂，艮為豺，震為麑。麑，鹿子也。兌折，故傷。坎為血、為獨、為憂，故曰哀。○在，汲古作生，依宋元本。泣，汲古作淬，依宋元本。</p><h3 id="益之巽" tabindex="-1">益之巽 <a class="header-anchor" href="#益之巽" aria-label="Permalink to “益之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>天地閉塞，仁智隱伏。商旅不行，利潤難得。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>初至四大過，故曰天地閉塞。震為仁，坎為智，皆伏不見，故曰隱伏。震為商旅，震伏，故不行。巽為利。○閉，汲古作鈐，依宋元本。</p><h3 id="益之兌" tabindex="-1">益之兌 <a class="header-anchor" href="#益之兌" aria-label="Permalink to “益之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>福德之士，歡悅日喜。夷吾相桓，三歸為臣，賞流子孫。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>通《艮》。互震為福德、為士、為喜，本卦互離，故曰日喜。震為桓、為歸，數三，故曰三歸。艮為臣、為孫。夷吾，管仲字，《論語》&quot;管氏有三歸&quot;，三歸，臺名。</p><h3 id="益之渙" tabindex="-1">益之渙 <a class="header-anchor" href="#益之渙" aria-label="Permalink to “益之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>上無飛鳥，下無走獸。擾亂未治，民勞於事。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>互艮為鳥，上巽為伏，故曰上無飛鳥。艮為獸，下坎隱伏，故曰下無走獸。震為走也。風散故擾亂。坎為民、為勞。○擾亂，宋元本作亂擾，依汲古。</p><h3 id="益之節" tabindex="-1">益之節 <a class="header-anchor" href="#益之節" aria-label="Permalink to “益之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>握鬥運樞，順天無憂，與樂並居。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>詳《謙》之《觀》。汲古多所行造德四字，依宋元本，汲古作《小過》林。</p><h3 id="益之中孚" tabindex="-1">益之中孚 <a class="header-anchor" href="#益之中孚" aria-label="Permalink to “益之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>戴盆望天，不見星辰。顧小失大，福逃牆外。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>盆，宋元本作瓶，牆作廬，依汲古。艮為戴，震為盆，艮為覆，震若戴盆於首，入不見天與星辰也。艮為天、為星，上巽為伏，亦不見也。艮為顧、為小，震為大，艮為牆，伏小過，震在艮外，故曰福逃牆外。</p><h3 id="益之小過" tabindex="-1">益之小過 <a class="header-anchor" href="#益之小過" aria-label="Permalink to “益之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>月削日衰，工女下機。宇宙滅明，不見三光。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>兌為月，艮為日，艮手為削，巽為工、為女，互坎為機，風散艮止，故曰工女下機。艮為天、為字宙，坎黑故滅明，故不見三光。艮為光，數三。汲古作《節》林。</p><h3 id="益之既濟" tabindex="-1">益之既濟 <a class="header-anchor" href="#益之既濟" aria-label="Permalink to “益之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>操戟剌魚，被髪立憂。虎脫我衣，狼取我袍，亡馬失財。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>此用《益》象。艮為戟，巽為魚、為髪，艮為虎狼，震為衣、為馬。○衣，汲古作輿，依宋元本。</p><h3 id="益之未濟" tabindex="-1">益之未濟 <a class="header-anchor" href="#益之未濟" aria-label="Permalink to “益之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>兩人俱醉，相與悖戾。心乖不同，爭訟匈匈。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>此仍用《益》象。坤迷故曰醉。震為人，坤數二，故曰兩人。坤為悖戾、為心，初至五正反震，故曰心乖、曰爭訟。</p>',322)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
